-- stochastic-processes implementation for FirstPassageTime
-- Assumptions: stochastic increments use the specified time step; physical SDE parameters use SI units and random draws are supplied or generated by the documented stream.

local Module = {}
function Module.FromPath(path,threshold,direction)
    for i=1,#path do
        local crossed=if direction=="below" then path[i]<=threshold else path[i]>=threshold
        if crossed then return i-1,{Hit=true,Value=path[i]} end
    end
    return nil,{Hit=false}
end

return Module
